from datetime import datetime
from enum import Enum

from pydantic import BaseModel, Field


class LogLevel(str, Enum):
    INFO = "INFO"
    WARNING = "WARNING"
    ERROR = "ERROR"
    CRITICAL = "CRITICAL"


class LogEntry(BaseModel):
    """Represents a single log entry generated by an application or service.

    Attributes:
    - timestamp: Date and time when the log event occurred.
    - service: Name of the application or service that generated the log.
    - level: Severity level of the log, such as INFO, WARNING, or ERROR.
    -  message: Description of the event or issue recorded in the log.
    """

    timestamp: datetime
    service: str = Field(min_length=1)
    level: LogLevel
    message: str = Field(min_length=1)
